[
  {
    "type": "heroSection",
    "title": "MCoT Engine — AI That Thinks Before It Designs",
    "description": "Most AI design tools generate images. MCoT plans campaigns. It's the world's first AI creative reasoning engine — a director in silicon that analyzes your brand, decomposes your request, orchestrates multiple models, and delivers production-ready output from a single conversation.",
    "input_placeholder": "Describe your brand and what you need to create...",
    "system_prompt": "You are MCoT, Lovart's Mind Chain of Thought reasoning engine. Analyze the user's request by decomposing their business objective, target audience, and creative needs. Plan a structured design strategy before generating any visual output. Coordinate across image, video, and audio models to maintain brand consistency.",
    "button_text": "Try MCoT Engine",
    "image_url": "https://cdn.sanity.io/images/o11tm2qe/production/73a9870b5cfe563ebc35a69551fd9c014f07a2f3-2160x1350.png",
    "suggestion": [
      {
        "value": "Create a summer campaign for my beachwear brand targeting women 22-30 in coastal cities",
        "label": "Summer Campaign"
      },
      {
        "value": "Launch campaign for our new running shoe — urban runners 25-40, use our existing brand kit",
        "label": "Product Launch"
      },
      {
        "value": "Design a complete brand identity for my sustainable coffee shop, from logo to social templates",
        "label": "Brand Identity"
      },
      {
        "value": "Generate 30 days of social media content for my e-commerce store, all brand-consistent",
        "label": "Social Media Pack"
      }
    ],
    "tip": "MCoT pauses 5-15 seconds to think before generating — that's the reasoning layer at work"
  },
  {
    "type": "threeColumnSection",
    "title": "How MCoT Works",
    "columns": [
      {
        "title": "Describe Your Goal",
        "description": "Tell MCoT what you need — a campaign, a brand kit, a product shoot. It decomposes your request into audience analysis, asset planning, and model selection before touching a single pixel.",
        "image_url": "https://assets-persist.lovart.ai/agent_images/98800dc8-d644-40b1-8442-3865137b6ecc.png"
      },
      {
        "title": "AI Reasons & Coordinates",
        "description": "MCoT orchestrates multiple models — Nano Banana Pro for images, Seedance 2.0 for video, Veo 3 for cinematic shots — and enforces brand consistency across every output.",
        "image_url": "https://assets-persist.lovart.ai/agent_images/da4b4705-9802-4e60-b637-ffed65818da1.png"
      },
      {
        "title": "Export & Publish",
        "description": "Receive a complete, brand-consistent asset suite — social posts, video teasers, email headers, product mockups — all export-ready from one conversation.",
        "image_url": "https://assets-persist.lovart.ai/agent_images/8f3f2384-8495-4075-b6d6-b90dd0cc6373.png"
      }
    ]
  },
  {
    "type": "contentSection",
    "sections": [
      {
        "title": "Strategic Reasoning, Not Just Generation",
        "description": "Before MCoT renders anything, it pauses to analyze your business context, target audience, and creative objectives. It decomposes vague requests like 'I need a campaign' into structured design plans — audience modeling, asset planning, visual strategy, and model orchestration. Traditional AI tools treat every prompt as a fresh start. MCoT maintains context across your entire project, remembering brand guidelines, previous decisions, and iteration history.",
        "button_text": "Learn How MCoT Reasons",
        "button_link": "https://www.lovart.ai/blog/inside-mcot-engine-ai-design-reasoning",
        "image_url": "https://cdn.sanity.io/images/o11tm2qe/production/73a9870b5cfe563ebc35a69551fd9c014f07a2f3-2160x1350.png"
      },
      {
        "title": "Cross-Model Coordination",
        "description": "Different design formats require different AI models — and they don't naturally coordinate. MCoT acts as a translation layer: it generates a unified creative brief that each model receives in its preferred format. Image models get detailed visual prompts. Video models get camera movement and scene composition. Audio models get mood and tempo directives. The result: your video thumbnail, email header, and Instagram carousel all share the same visual DNA.",
        "button_text": "Explore Models",
        "button_link": "https://www.lovart.ai",
        "image_url": "https://cdn.sanity.io/images/o11tm2qe/production/bc6e807affb256c5fc80047f7df8747ea4f0ebe4-2160x1350.png"
      },
      {
        "title": "Brand Memory That Survives",
        "description": "In traditional AI tools, every session is amnesiac. Close the tab and the AI forgets everything. MCoT maintains persistent brand state — color palettes, typography, layout preferences, editorial decisions — embedded in its reasoning chain. Start a project Monday, pick it up Thursday, and the AI remembers exactly what you were trying to accomplish and why.",
        "button_text": "Try Thinking Mode",
        "button_link": "https://www.lovart.ai",
        "image_url": "https://cdn.sanity.io/images/o11tm2qe/production/11990086076078e21c2cf45e1e7677248da4aa5c-1280x800.png"
      }
    ]
  },
  {
    "type": "textImageSection",
    "title": "Touch Edit + Layer Explosion — The Proof AI Understands",
    "description": "Click any object in a generated image and describe what you want changed — no masking, no selections. MCoT understands spatial and semantic structure. Edit Elements decomposes any image into independent layers with one click. Move the product, the shadow follows. Change the background, the lighting adjusts. This is AI doing design work, not just generating pixels.",
    "button_text": "See Touch Edit in Action",
    "button_link": "https://www.lovart.ai/docs/canvas/edit-element",
    "image_url": "https://cdn.sanity.io/images/o11tm2qe/production/11990086076078e21c2cf45e1e7677248da4aa5c-1280x800.png"
  },
  {
    "type": "faqSection",
    "faq": [
      {
        "question": "What is MCoT Engine?",
        "answer": "MCoT (Mind Chain of Thought) is the core reasoning layer that powers Lovart's AI Design Agent. Unlike standard image generators that process prompts as single-turn transactions, MCoT decomposes your request into a structured design plan — analyzing business context, planning assets, selecting the right AI models, and enforcing brand consistency across all outputs."
      },
      {
        "question": "How is MCoT different from writing a detailed prompt?",
        "answer": "A detailed prompt gives a model more instructions, but still processes them as a single generation task with no planning, coordination, or memory. MCoT decomposes your request, orchestrates multiple specialized models, and maintains context across your entire project. It's the difference between giving a chef a recipe and giving a kitchen manager a menu to execute."
      },
      {
        "question": "What models does MCoT work with?",
        "answer": "MCoT coordinates across Lovart's full model library — image models (Nano Banana Pro, Seedream 4.0, Flux, Recraft V3), video models (Seedance 2.0, Sora 2, Veo 3, Kling), and supporting tools. The engine selects the appropriate model per task based on output requirements."
      },
      {
        "question": "Can I use MCoT without the thinking phase?",
        "answer": "Yes. Lovart offers a Fast Mode that skips the MCoT reasoning chain and generates directly — ideal for rapid brainstorming, mood boarding, and quick iterations. You can switch between Thinking Mode and Fast Mode at any point in a project."
      },
      {
        "question": "Does MCoT remember my brand across projects?",
        "answer": "Brand context is maintained within projects using Brand Kit. The engine treats brand rules as persistent state — consistency is enforced automatically rather than requiring manual re-specification each session. You can reference brand kits across projects using the @ mention system."
      },
      {
        "question": "Who built MCoT?",
        "answer": "MCoT was developed by Lovart, a product of LiblibAI — a Beijing and San Francisco-based AI company founded in 2023 by Melvin Chen (CEO) and Wang Haofan (CTO, Carnegie Mellon alumnus known for InstantID and InstantStyle). LiblibAI closed a $130 million Series B round led by Sequoia China and CMC Capital in August 2025."
      },
      {
        "question": "Is MCoT available for free?",
        "answer": "Lovart offers a free tier that gives you access to MCoT-powered Thinking Mode with monthly usage credits. The Pro subscription — priced under $90/month — unlocks unlimited usage, priority model access, and commercial licensing for agency-grade design output."
      },
      {
        "question": "What kind of projects can MCoT handle?",
        "answer": "MCoT handles end-to-end design projects — from single social media posts to complete multi-format campaigns with coordinated image, video, and audio assets. It's used by graphic designers, marketing teams, e-commerce sellers, content creators, and small business owners who need professional, brand-consistent output without managing multiple specialized tools."
      },
      {
        "question": "What makes MCoT different from Midjourney or DALL-E?",
        "answer": "Midjourney and DALL-E are image generators — they produce one image per prompt with no memory, no planning, and no coordination across formats. MCoT is a design reasoning engine that plans campaigns, coordinates multiple AI models, maintains brand consistency, and delivers complete asset suites from a single conversation. It's a design director, not a camera."
      }
    ]
  }
]
